import numpy as np

# MECHANISM: Use a piecewise linear function with a different breakpoint structure to prioritize bins based on remaining capacity.

def priority(item, bins):
    capacity = 150
    breakpoints = [0, 50, 100, 125, 140]
    weights = [0.99, 0.95, 0.9, 0.8, 0.7]

    def s(b, item):
        g = b - item
        for i, bp in enumerate(breakpoints):
            if g <= bp:
                return weights[i]
        return weights[-1]

    return np.array([s(b, item) for b in bins])

